import{_ as t,c as a,o as i,ag as n}from"./chunks/framework.CoPVQkzc.js";const u=JSON.parse('{"title":"Web Administrator","description":"Administering OIE from a browser","frontmatter":{"title":"Web Administrator","description":"Administering OIE from a browser"},"headers":[],"relativePath":"engine/web_administrator.md","filePath":"engine/web_administrator.md","lastUpdated":1788476353000}'),s={name:"engine/web_administrator.md"};function r(o,e,l,d,h,p){return i(),a("div",null,e[0]||(e[0]=[n('<h1 id="web-administrator" tabindex="-1">Web Administrator <a class="header-anchor" href="#web-administrator" aria-label="Permalink to &quot;Web Administrator&quot;">​</a></h1><p>OIE can be administered from a browser. The web administrator is open source under MPL 2.0 and installs as an ordinary extension, so the engine itself needs no modification. It works read/write against the same REST API the desktop Administrator uses.</p><p>This is not the Mirth Connect™ &quot;Web Dashboard&quot;, which OIE does not have. It is a full administrator, not a status page.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>Requires OIE 4.6.0.</strong></p></div><h2 id="what-it-replaces" tabindex="-1">What it replaces <a class="header-anchor" href="#what-it-replaces" aria-label="Permalink to &quot;What it replaces&quot;">​</a></h2><p>Getting into the desktop Administrator has always taken several steps: install a launcher, supply or accept a Java runtime with JavaFX, let the launcher pull down the client, then log in. The web administrator collapses that to opening a browser and logging in.</p><p>Both clients talk to the same engine, so there is no cutover. The desktop Administrator continues to work exactly as before while people move across at whatever pace suits them.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>The web administrator is read/write across the areas you would expect to use day to day.</p><table tabindex="0"><thead><tr><th>Area</th><th>Capability</th></tr></thead><tbody><tr><td><strong>Channels</strong></td><td>Full channel editing, including source and destination configuration, filters, and transformers, plus deployment</td></tr><tr><td><strong>Messages</strong></td><td>Search, browse, reprocess, and resend, with the full message tree for any selected message</td></tr><tr><td><strong>Dashboard</strong></td><td>Live channel status, throughput, and deployment state</td></tr><tr><td><strong>Extensions</strong></td><td>Installed extensions are listed, and any that ship a web interface are served automatically</td></tr><tr><td><strong>Themes</strong></td><td>Light and dark</td></tr></tbody></table><p>Three details are worth calling out because they determine whether what you see in the browser matches what the engine actually does.</p><p><strong>Message serialization runs through the engine&#39;s own data type serializers.</strong> The message tree is produced server-side by the same code that builds <code>msg</code> and <code>tmp</code> at runtime, so the tree matches the runtime representation byte for byte rather than approximating it in the browser.</p><p><strong>JavaScript is validated by the engine&#39;s Rhino.</strong> Scripts are compiled by the same engine that will execute them, so a script that validates in the browser is a script that compiles at runtime. Browser-side syntax checking would not give you that.</p><p><strong>Plugin interfaces are served by the engine.</strong> An installed extension that ships a web UI is detected and served without any separate deployment step, the community plugin store included. Plugins follow the engine they are installed on.</p><p>The script editor is Monaco, bundled and served locally rather than pulled from a CDN, so it works on air-gapped servers. There is a plain-editor fallback if it cannot load.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>The web administrator ships as the <strong>Web Support</strong> extension. It installs the administrator into the engine&#39;s own embedded Jetty, along with the server-side APIs it needs for message serialization, JavaScript validation, and serving other plugins&#39; web interfaces.</p><ol><li>In the desktop Administrator, go to <strong>Extensions</strong> and install the Web Support extension</li><li>Restart the engine</li><li>Browse to <code>https://&lt;host&gt;:8443/oie-webadmin/</code></li></ol><p>It is served on the engine&#39;s existing port and behind the same credentials, so there is no second service to secure and no separate user directory.</p><p>Node.js and Docker deployments are also available if you would rather run the administrator separately from the engine.</p><p>Source and releases: <a href="https://github.com/gibson9583/oie-web-support-plugin" target="_blank" rel="noreferrer">gibson9583/oie-web-support-plugin</a></p><h2 id="plugins-in-the-web-administrator" tabindex="-1">Plugins in the Web Administrator <a class="header-anchor" href="#plugins-in-the-web-administrator" aria-label="Permalink to &quot;Plugins in the Web Administrator&quot;">​</a></h2><p>The web administrator does not treat its own features as special. Its connectors, data types, transformer steps, attachment viewers, and dashboard tabs are all plugins loaded through the same mechanism your own plugin would use.</p><p>A web plugin is a directory containing a manifest and a compiled React entry point, placed in a plugins directory and picked up on the next browser refresh.</p><p>If you already maintain an engine extension with a Swing panel, the engine half is unchanged. You write only the web interface, calling the REST endpoints the extension already exposes. Each Swing extension point has a web counterpart:</p><ul><li>Dashboard tabs and dashboard columns</li><li>Settings panels</li><li>Channel tabs and channel tasks</li><li>Transformer steps and filter rules</li><li>Attachment viewers</li><li>Connector panels</li><li>Data types</li><li>Transmission modes</li><li>Resource types</li><li>The authorization controller</li></ul><p>Because discovery happens at runtime, one extension install serves both administrators. Nobody maintains a separate web build, and a plugin cannot drift out of step with the engine it is installed on.</p><p>Plugin development guide: <a href="https://github.com/gibson9583/oie-web-client/blob/main/web-administrator/PLUGINS.md" target="_blank" rel="noreferrer">PLUGINS.md</a></p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./desktop_administrator.html">Desktop Administrator</a> - the desktop client</li><li><a href="./extension_catalog.html">Extension Catalog</a> - the plugin catalog and extension model</li><li><a href="./dashboard_and_monitoring.html">Dashboard and Monitoring</a></li><li><a href="./security_and_compliance.html">Security and Compliance</a></li></ul>',30)]))}const m=t(s,[["render",r]]);export{u as __pageData,m as default};
